import mongoose from 'mongoose';

/**
 * Order Counter Schema
 *
 * WHY THIS EXISTS
 * ---------------
 * The order number used to be generated by counting the store's orders and
 * adding one:
 *
 *     const count = await Order.countDocuments({ store });
 *     this.orderNumber = `AUR-${String(count + 1).padStart(5, '0')}`;
 *
 * That is a check-then-act race. Two orders created at the same moment both
 * read the same count and both compute the same number; the unique index on
 * `{ store, orderNumber }` then rejects one of them — a 500 *after* the
 * customer has already paid. Under load the gap is invisible most of the
 * time and the failure is rare but real.
 *
 * A counter collection fixes it: `findOneAndUpdate({ $inc: { sequence: 1 } })`
 * is atomic, so every caller gets a different number. The unique index stays
 * as a last line of defence.
 */
const OrderCounterSchema = new mongoose.Schema(
  {
    // ============================================
    // TENANT
    // ============================================
    store: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Store',
      required: true,
      index: true,
    },

    // ============================================
    // SEQUENCE
    // ============================================
    // The last number handed out for this store.
    sequence: {
      type: Number,
      default: 0,
      min: 0,
    },
  },
  {
    timestamps: true,
  }
);

// One counter per store
OrderCounterSchema.index({ store: 1 }, { unique: true });

const OrderCounter = mongoose.model('OrderCounter', OrderCounterSchema);

export default OrderCounter;
